/bin/bash -c "python3 - <<'PY'
from math import isclose

def tent(x):
    return max(0.25-abs(x-0.5),0.0)

def fold(x):
    if x<=1:
        return 0.125+0.75*x
    if x<=2:
        t=x-1
        return 0.875+0.75*(t-t*t)
    return 2.375-0.75*x

def f0(x): return tent(x)
def f1(x): return tent((x-0.125)/0.75)

xs=[i/10000 for i in range(10001)]
print('Counterexample check: f0(x) versus f1(fold(x)) on the observed interval')
print('Maximum pointwise difference:',max(abs(f0(x)-f1(fold(x))) for x in xs))
print('Outside-window values at x=2.5:',f0(2.5),f1(fold(2.5)))
for d in [6,10,100]:
    e=max(abs(fold(x+1/d)-fold(x)) for x in xs)
    print('d=',d,'shift error=',e,'allowed=',1/d,'shifted endpoint images=',(fold(1/d),fold(1+1/d)))
print('Template support x intervals:',(0.25,0.75),(0.3125,0.6875))
print('Deformed template support x intervals: f0 composed with fold:',[(1/6,5/6),(13/6,17/6)])
print('Deformed template support x intervals: f1 composed with fold:',[(0.25,0.75),(2.25,2.75)])
PY"
